<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Hopely Care — Admin</title>
<style>
:root{font-family:system-ui,sans-serif;color:#25374b;background:#f3f7fa}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0;border-radius:12px;padding:11px 17px;background:#3477a5;color:white}button.secondary{background:#e7eff5;color:#285779}button:disabled{opacity:.5;cursor:default}input,textarea,select{width:100%;border:1px solid #cfdae3;border-radius:10px;padding:11px;background:white}textarea{min-height:110px}label{display:block;margin:14px 0 6px;font-size:14px}h1,h2{margin-top:0}small{color:#60758b}.card{background:white;border-radius:20px;padding:24px;box-shadow:0 4px 24px #294d6e08;margin-bottom:18px}#login{max-width:440px;margin:10vh auto;padding:24px}.layout{display:grid;grid-template-columns:235px 1fr;min-height:100vh}aside{padding:28px 18px;background:#e8f0f7}aside button{display:block;width:100%;text-align:left;margin:8px 0;background:transparent;color:#285779}aside button.active{background:#3477a5;color:white}main{padding:32px;min-width:0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:18px}.toolbar input{flex:1;min-width:180px}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:14px;border-bottom:1px solid #edf1f5;vertical-align:top}td{max-width:360px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fa;padding:16px;border-radius:12px}dialog{border:0;border-radius:20px;width:min(760px,94vw);max-height:90vh;padding:26px}dialog::backdrop{background:#18344877}.error{color:#a03232;background:#fff0ef;padding:12px;border-radius:10px;white-space:pre-wrap}.success{color:#216b4c}.hidden{display:none!important}.brand{font-weight:750;font-size:22px;margin-bottom:24px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center}.check{display:flex;gap:10px;align-items:center}.check input{width:auto}img{max-width:100%;max-height:320px;border-radius:12px}@media(max-width:760px){.layout{display:block}aside{padding:16px}aside nav{display:flex;overflow:auto}aside button{width:auto;white-space:nowrap}main{padding:18px}.brand{margin-bottom:12px}}
</style>
</head>
<body>
<section id="login"><div class="card"><div class="brand">Hopely Care</div><h1>Masuk admin</h1><p>Kelola konten dan dukungan komunitas dari satu tempat.</p><form id="loginForm"><label>Email</label><input name="email" type="email" required autocomplete="username"><label>Kata sandi</label><input name="password" type="password" required autocomplete="current-password"><p id="loginError" class="error hidden"></p><button style="margin-top:20px" type="submit">Masuk dashboard</button></form></div></section>
<section id="workspace" class="layout hidden"><aside><div class="brand">Hopely Care <small>Admin</small></div><nav id="nav"></nav><button id="logout">Keluar akun</button></aside><main><div class="row"><h1 id="heading"></h1><small id="identity"></small></div><p id="notice" class="hidden"></p><div id="content"></div></main></section>
<dialog id="editor"><div class="row"><h2 id="editorTitle"></h2><button class="secondary" id="closeEditor">Tutup</button></div><div id="editorBody"></div></dialog>
<script>
'use strict';
let token=sessionStorage.getItem('hopely.admin.token'), user=null, module='activities', page=1, search='', generation=0;
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={activities:'Aktivitas kesehatan',knowledge:'Dokumen pengetahuan',communities:'Komunitas',reports:'Laporan',moderation:'Moderasi konten',users:'Pengguna','support-alerts':'Bantuan cepat',audit:'Audit log'};
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{Accept:'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok){if(r.status===401) signedOut();throw new Error(j.message||JSON.stringify(j.error||j.errors||j));}return j.data??j;}
function notice(message,error=false){$('notice').textContent=message;$('notice').className=error?'error':'success';}
function signedOut(){token=null;user=null;sessionStorage.removeItem('hopely.admin.token');$('workspace').classList.add('hidden');$('login').classList.remove('hidden');$('editor').close();}
function modules(){if(['ADMIN','SUPER_ADMIN'].includes(user.role))return ['activities','knowledge','communities','reports',...(user.role==='ADMIN'?['moderation']:[]),'users','support-alerts','audit'];if(user.role==='CONTENT_ADMIN')return ['activities','knowledge'];if(user.role==='COMMUNITY_MODERATOR')return ['communities','reports'];return [];}
function signedIn(){const available=modules();if(!available.length){signedOut();return;}$('login').classList.add('hidden');$('workspace').classList.remove('hidden');$('identity').textContent=user.email+' · '+user.role;$('nav').replaceChildren();for(const key of available){const b=document.createElement('button');b.textContent=labels[key];b.onclick=()=>{module=key;page=1;search='';load();};b.dataset.module=key;$('nav').append(b);}module=available[0];load();}
$('loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('loginError').classList.add('hidden');try{const data=await api('admin/auth/login','POST',Object.fromEntries(new FormData(e.target)));token=data.token;user=data.user;sessionStorage.setItem('hopely.admin.token',token);e.target.reset();signedIn();}catch(err){$('loginError').textContent=err.message;$('loginError').classList.remove('hidden');}finally{b.disabled=false;}};
$('logout').onclick=async()=>{try{await api('auth/logout','POST',{});signedOut();}catch(e){notice(e.message,true);}};
$('closeEditor').onclick=()=>$('editor').close();
function dialog(title,html){$('editorTitle').textContent=title;$('editorBody').innerHTML=html;if(!$('editor').open)$('editor').showModal();}
async function load(){const version=++generation;$('heading').textContent=labels[module];$('notice').classList.add('hidden');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.module===module));$('content').textContent='Memuat…';if(module==='knowledge'){knowledgeForm();return;}if(module==='moderation'){moderation();return;}try{const data=await api(`admin/workspace/${module}?page=${page}&search=${encodeURIComponent(search)}`);if(version!==generation)return;const rows=data.data??[];$('content').innerHTML=`<div class="toolbar"><input id="search" placeholder="Cari ${esc(labels[module].toLowerCase())}" value="${esc(search)}"><button id="searchButton">Cari</button>${module==='activities'?'<button id="add">Tambah aktivitas</button>':''}</div><div class="card table"><table><thead><tr><th>Nama / informasi</th><th>Status / tanggal</th><th>Aksi</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.title??r.name??r.event??r.reason??r.id)}${r.email?'<br><small>'+esc(r.email)+'</small>':''}</td><td>${esc(r.status??r.role??(r.active===undefined?'':r.active?'Aktif':'Nonaktif'))}<br><small>${esc(r.created_at)}</small></td><td><button class="secondary" data-row="${i}">${module==='activities'?'Edit':'Detail'}</button></td></tr>`).join('')||'<tr><td colspan="3">Belum ada data.</td></tr>'}</tbody></table></div><div class="toolbar"><button id="prev" ${page<=1?'disabled':''}>Sebelumnya</button><span>Halaman ${page} / ${data.last_page}</span><button id="next" ${page>=data.last_page?'disabled':''}>Berikutnya</button></div>`;$('searchButton').onclick=()=>{search=$('search').value;page=1;load();};$('search').onkeydown=e=>{if(e.key==='Enter')$('searchButton').click();};$('prev').onclick=()=>{page--;load();};$('next').onclick=()=>{page++;load();};if($('add'))$('add').onclick=()=>activityForm();document.querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>{const row=rows[+b.dataset.row];if(module==='activities')activityForm(row);else dialog(labels[module],'<pre>'+esc(JSON.stringify(row,null,2))+'</pre>');});}catch(e){if(version===generation){$('content').textContent='Data belum dapat dimuat.';notice(e.message,true);}}}
function field(key,label,value='',type='text',required=true){return `<label for="f_${key}">${esc(label)}</label>${type==='textarea'?`<textarea id="f_${key}" name="${key}" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="f_${key}" name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''}>`}`;}
function activityForm(row={}){dialog(row.id?'Edit aktivitas':'Tambah aktivitas',`<form id="activityForm">${field('title','Judul',row.title)}${field('description','Deskripsi',row.description,'textarea')}${field('category','Kategori',row.category)}${field('duration_minutes','Durasi (1–60 menit)',row.duration_minutes??5,'number')}${field('suitability_tags','Tag kesesuaian — satu per baris',(row.suitability_tags??[]).join('\n'),'textarea')}${field('steps','Langkah — satu per baris',(row.steps??[]).join('\n'),'textarea')}${field('contraindication_notes','Catatan perhatian',row.contraindication_notes,'textarea',false)}<label class="check"><input name="medically_reviewed" type="checkbox" ${row.medically_reviewed?'checked':''}>Sudah ditinjau secara medis</label><label class="check"><input name="active" type="checkbox" ${row.active!==false?'checked':''}>Aktif</label><p id="formError" class="error hidden"></p><button type="submit">Simpan aktivitas</button></form>`);$('f_duration_minutes').min=1;$('f_duration_minutes').max=60;$('activityForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.duration_minutes=Number(d.duration_minutes);for(const key of ['steps','suitability_tags'])d[key]=d[key].split('\n').map(s=>s.trim()).filter(Boolean);d.active=e.target.elements.active.checked;d.medically_reviewed=e.target.elements.medically_reviewed.checked;await api('admin/activities'+(row.id?'/'+row.id:''),row.id?'PUT':'POST',d);$('editor').close();await load();notice('Aktivitas berhasil disimpan.');}catch(err){$('formError').textContent=err.message;$('formError').classList.remove('hidden');}finally{button.disabled=false;}};}
function knowledgeForm(){$('content').innerHTML=`<div class="card"><h2>Publikasikan dokumen pengetahuan</h2><p>Dokumen dikirim ke basis pengetahuan AI dan pustaka artikel mobile.</p><form id="knowledgeForm">${field('source_id','ID sumber unik')}${field('title','Judul')}${field('publisher','Penerbit')}${field('source_url','URL sumber','','url',false)}${field('published_at','Tanggal publikasi','','date',false)}${field('document_version','Versi dokumen','1')}${field('reviewed_by','Nama peninjau')}${field('text','Naskah artikel','','textarea')}<label class="check"><input name="reviewed" type="checkbox" required>Dokumen telah ditinjau</label><button type="submit">Simpan dan indeks dokumen</button></form></div>`;$('knowledgeForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.reviewed=true;for(const k of ['source_url','published_at'])if(!d[k])d[k]=null;await api('admin/knowledge/ingest','POST',d);e.target.reset();notice('Dokumen berhasil dipublikasikan.');}catch(err){notice(err.message,true);}finally{b.disabled=false;}};}
let kind='post';
async function moderation(){try{const data=await api(`community/moderation?kind=${kind}&page=${page}`);if(module!=='moderation')return;$('content').innerHTML=`<div class="toolbar"><select id="kind"><option value="post">Postingan</option><option value="comment">Komentar</option><option value="report">Laporan</option></select></div><div id="queue"></div><div class="toolbar"><button id="prev" ${page<=1?'disabled':''}>Sebelumnya</button><span>Halaman ${page} / ${data.last_page}</span><button id="next" ${page>=data.last_page?'disabled':''}>Berikutnya</button></div>`;$('kind').value=kind;$('kind').onchange=e=>{kind=e.target.value;page=1;moderation();};$('prev').onclick=()=>{page--;moderation();};$('next').onclick=()=>{page++;moderation();};if(!data.items.length)$('queue').textContent='Tidak ada konten menunggu peninjauan.';for(const row of data.items){const card=document.createElement('section');card.className='card';card.innerHTML=`<h2>${esc(row.community_name)}</h2><small>${esc(row.reason??row.moderation_status??row.status)}</small><pre>${esc(row.content)}</pre>${row.description?'<p>'+esc(row.description)+'</p>':''}<div class="toolbar"></div>`;$('queue').append(card);if(row.has_image&&row.post_id){const r=await fetch('/api/community/posts/'+encodeURIComponent(row.post_id)+'/image',{headers:{Authorization:'Bearer '+token}});if(r.ok){const url=URL.createObjectURL(await r.blob()),img=document.createElement('img');img.onload=()=>URL.revokeObjectURL(url);img.src=url;img.alt='Gambar konten yang ditinjau';card.prepend(img);}}const actions=kind==='report'?{remove:'Hapus konten',dismiss:'Tutup laporan'}:{...(row.can_approve?{approve:'Setujui'}:{}),remove:'Hapus konten'};for(const [action,label]of Object.entries(actions)){const b=document.createElement('button');b.textContent=label;b.onclick=()=>review(row,action);card.querySelector('.toolbar').append(b);}}}catch(e){notice(e.message,true);}}
function review(row,action){dialog('Keputusan moderasi',`<form id="reviewForm"><p>${esc(row.content)}</p>${field('note','Catatan keputusan (3–500 karakter)','','textarea')}<p id="reviewError" class="error hidden"></p><button type="submit">Konfirmasi keputusan</button></form>`);$('f_note').minLength=3;$('f_note').maxLength=500;$('reviewForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api(`community/moderation/${row.kind}/${row.id}`,'POST',{action,note:e.target.elements.note.value,revision:row.revision});$('editor').close();await moderation();notice('Keputusan moderasi disimpan.');}catch(err){$('reviewError').textContent=err.message;$('reviewError').classList.remove('hidden');}finally{b.disabled=false;}};}
const originalActivityForm = activityForm;
activityForm = function(row={}) {
    originalActivityForm(row);
    const form = $('activityForm');
    const image = document.createElement('div');
    image.innerHTML = field('image_url','URL gambar latihan (HTTPS, opsional)',row.image_url??'','url',false)+'<p><small>Gunakan gambar yang menjelaskan latihan. Gambar ini ditampilkan pada kartu aktivitas pasien.</small></p><img id="activityPreview" alt="Pratinjau gambar latihan" class="hidden">';
    form.prepend(image);
    const preview = () => { const value = $('f_image_url').value; const img = $('activityPreview'); img.classList.toggle('hidden',!value.startsWith('https://')); if(value.startsWith('https://')) img.src=value; };
    $('f_image_url').oninput=preview;
    $('activityPreview').onerror=()=> $('activityPreview').classList.add('hidden');
    preview();
};
function communityForm(row={}) {
    dialog(row.id?'Edit komunitas':'Tambah komunitas',`<form id="communityForm">${field('name','Nama komunitas',row.name)}${field('slug','Slug unik (huruf kecil dan tanda hubung)',row.slug)}${field('description','Deskripsi',row.description,'textarea')}${field('category','Kategori',row.category)}${field('cancer_type','Jenis kanker (opsional)',row.cancer_type,'text',false)}${field('treatment_phase','Fase perawatan (opsional)',row.treatment_phase,'text',false)}${field('support_type','Jenis dukungan (opsional)',row.support_type,'text',false)}${field('image_url','URL gambar HTTPS (opsional)',row.image_url,'url',false)}<label class="check"><input name="is_active" type="checkbox" ${row.is_active!==false?'checked':''}>Komunitas aktif</label><p><small>Menonaktifkan komunitas menyembunyikannya dari penjelajahan pasien tanpa menghapus riwayat anggota.</small></p><p id="communityError" class="error hidden"></p><button type="submit">Simpan komunitas</button></form>`);
    if(!row.id) $('f_name').oninput=()=>{ $('f_slug').value=$('f_name').value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); };
    $('communityForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.is_active=e.target.elements.is_active.checked;await api('admin/communities'+(row.id?'/'+row.id:''),row.id?'PUT':'POST',d);$('editor').close();await load();notice('Komunitas berhasil disimpan.');}catch(err){$('communityError').textContent=err.message;$('communityError').classList.remove('hidden');}finally{b.disabled=false;}};
}
const originalLoad = load;
load = async function() {
    if(module!=='communities') return originalLoad();
    const version=++generation;
    $('heading').textContent=labels.communities;
    $('notice').classList.add('hidden');
    document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.module===module));
    $('content').textContent='Memuat komunitas…';
    try {
        const data=await api(`admin/workspace/communities?page=${page}&search=${encodeURIComponent(search)}`);
        if(version!==generation)return;
        const canEdit=['ADMIN','SUPER_ADMIN'].includes(user.role);
        $('content').innerHTML=`<div class="toolbar"><input id="communitySearch" placeholder="Cari komunitas" value="${esc(search)}"><button id="findCommunity">Cari</button>${canEdit?'<button id="newCommunity">Tambah komunitas</button>':''}</div><div class="card table"><table><thead><tr><th>Komunitas</th><th>Anggota aktif</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${data.data.map((r,i)=>`<tr><td><strong>${esc(r.name)}</strong><br><small>${esc(r.category)}</small><p>${esc(r.description)}</p></td><td>${Number(r.active_members_count)}</td><td>${r.is_active?'Aktif':'Nonaktif'}</td><td><button data-community="${i}" class="secondary">${canEdit?'Edit':'Detail'}</button></td></tr>`).join('')||'<tr><td colspan="4">Belum ada komunitas.</td></tr>'}</tbody></table></div><div class="toolbar"><button id="previousCommunity" ${page<=1?'disabled':''}>Sebelumnya</button><span>Halaman ${page} / ${data.last_page}</span><button id="nextCommunity" ${page>=data.last_page?'disabled':''}>Berikutnya</button></div>`;
        $('findCommunity').onclick=()=>{search=$('communitySearch').value;page=1;load();};
        $('communitySearch').onkeydown=e=>{if(e.key==='Enter')$('findCommunity').click();};
        if(canEdit)$('newCommunity').onclick=()=>communityForm();
        document.querySelectorAll('[data-community]').forEach(b=>b.onclick=()=>{const row=data.data[+b.dataset.community];canEdit?communityForm(row):dialog('Detail komunitas','<pre>'+esc(JSON.stringify(row,null,2))+'</pre>');});
        $('previousCommunity').onclick=()=>{page--;load();};$('nextCommunity').onclick=()=>{page++;load();};
    } catch(e) { if(version===generation){$('content').textContent='Komunitas belum dapat dimuat.';notice(e.message,true);} }
};
if(token)api('me').then(d=>{user=d.user;signedIn();}).catch(()=>signedOut());
</script>
</body></html>
